Route::get('/ess/request-center-entry', function (Request $request) {
    auth()->logout();
    $request->session()->invalidate();
    $request->session()->regenerateToken();
    $request->session()->put('url.intended', route('ess.request-center'));

    return redirect()->route('login');
})->name('ess.request-center.entry');

